import MaterialIcons from "@expo/vector-icons/MaterialIcons";
import { router } from "expo-router";
import { useEffect, useState } from "react";
import { ActivityIndicator, Alert, RefreshControl, ScrollView, StyleSheet, Text, TextInput, TouchableOpacity, View } from "react-native";
import { ScreenContainer } from "@/components/screen-container";
import { djangoApi } from "@/lib/django-api";

type Payout={id:number;amount:string;currency:string;status:string;reference:string;created_at:string};
type Finance={vendor:number;vendor_name:string;currency:string;earned:string;paid:string;pending:string;available:string;payouts:Payout[]};

export default function VendorWalletScreen(){
 const [finance,setFinance]=useState<Finance|null>(null); const [amount,setAmount]=useState(""); const [loading,setLoading]=useState(true); const [refreshing,setRefreshing]=useState(false); const [sending,setSending]=useState(false);
 async function load(){try{setFinance(await djangoApi<Finance>("/api/vendor-finance/summary/"))}catch{setFinance(null)}finally{setLoading(false);setRefreshing(false)}}
 useEffect(()=>{load()},[]);
 async function requestPayout(){if(!amount||Number(amount)<=0){Alert.alert("مبلغ غير صالح","أدخل قيمة موجبة.");return} if(finance&&Number(amount)>Number(finance.available)){Alert.alert("الرصيد غير كافٍ",`المتاح للسحب ${finance.available} ${finance.currency}.`);return}setSending(true);try{await djangoApi("/api/vendor-finance/request_payout/",{method:"POST",body:JSON.stringify({amount})});setAmount("");Alert.alert("تم الطلب","أُرسل طلب السحب إلى الإدارة للمراجعة.");await load()}catch(error){Alert.alert("تعذر إنشاء طلب السحب",error instanceof Error?error.message:"حدث خطأ")}finally{setSending(false)}}
 if(loading)return <ScreenContainer><View style={styles.center}><ActivityIndicator color="#E11D48"/><Text style={styles.muted}>جارٍ تحميل المستحقات...</Text></View></ScreenContainer>;
 return <ScreenContainer className="bg-[#F6F7F9]" edges={["top","bottom","left","right"]}>
  <View style={styles.header}><TouchableOpacity onPress={()=>router.back()} style={styles.iconBtn}><MaterialIcons name="arrow-forward" size={23} color="#111"/></TouchableOpacity><View style={styles.headerCopy}><Text style={styles.title}>مستحقات متجري</Text><Text style={styles.subtitle}>{finance?.vendor_name||""}</Text></View><View style={styles.headerIcon}><MaterialIcons name="payments" size={18} color="#FFF"/></View></View>
  <ScrollView contentContainerStyle={styles.page} refreshControl={<RefreshControl refreshing={refreshing} onRefresh={()=>{setRefreshing(true);load()}} />}>
   <View style={styles.hero}><View style={styles.heroTop}><View style={styles.heroIcon}><MaterialIcons name="account-balance-wallet" size={20} color="#FFF"/></View><Text style={styles.heroLabel}>المتاح للسحب</Text></View><Text style={styles.heroAmount}>{finance?.available||"0.00"} <Text style={styles.heroCurrency}>{finance?.currency||"YER"}</Text></Text><View style={styles.heroMeta}><Text style={styles.heroMetaText}>المكتسب {finance?.earned||"0"}</Text><Text style={styles.heroMetaText}>المعلق {finance?.pending||"0"}</Text></View></View>
   <View style={styles.metrics}><Metric icon="trending-up" label="المكتسب" value={finance?.earned||"0"}/><Metric icon="done-all" label="المدفوع" value={finance?.paid||"0"}/><Metric icon="hourglass-top" label="معلق" value={finance?.pending||"0"}/></View>
   <View style={styles.card}><View style={styles.cardHead}><View style={styles.cardIcon}><MaterialIcons name="arrow-upward" size={17} color="#E11D48"/></View><View><Text style={styles.cardTitle}>طلب سحب جديد</Text><Text style={styles.cardHint}>يُراجع من الإدارة قبل التحويل</Text></View></View><View style={styles.amountField}><Text style={styles.currencyPill}>{finance?.currency||"YER"}</Text><TextInput value={amount} onChangeText={setAmount} placeholder="0.00" keyboardType="decimal-pad" style={styles.input} textAlign="right"/></View><TouchableOpacity style={[styles.primary,sending&&styles.disabled]} disabled={sending} onPress={requestPayout}><MaterialIcons name="send" size={18} color="#FFF"/><Text style={styles.primaryText}>{sending?"جارٍ الإرسال...":"إرسال طلب السحب"}</Text></TouchableOpacity></View>
   <View style={styles.sectionHead}><Text style={styles.sectionTitle}>سجل طلبات السحب</Text><Text style={styles.sectionHint}>{finance?.payouts?.length||0} طلب</Text></View>
   <View style={styles.card}>{finance?.payouts?.length?finance.payouts.map((p,index)=><View key={p.id} style={[styles.payout,index===0&&styles.firstPayout]}><View style={styles.statusPill}><View style={[styles.statusDot,{backgroundColor:statusColor(p.status)}]}/><Text style={[styles.statusText,{color:statusColor(p.status)}]}>{translate(p.status)}</Text></View><View style={styles.payoutCopy}><Text style={styles.payoutAmount}>{p.amount} {p.currency}</Text><Text style={styles.reference}>{p.reference}</Text><Text style={styles.date}>{new Date(p.created_at).toLocaleDateString("ar-YE")}</Text></View></View>):<View style={styles.empty}><MaterialIcons name="receipt-long" size={32} color="#C7C7C7"/><Text style={styles.emptyText}>لا توجد طلبات سحب حتى الآن.</Text></View>}</View>
  </ScrollView>
 </ScreenContainer>
}
function Metric({icon,label,value}:{icon:string;label:string;value:string}){return <View style={styles.metric}><View style={styles.metricIcon}><MaterialIcons name={icon as any} size={17} color="#111"/></View><Text style={styles.metricValue} numberOfLines={1}>{value}</Text><Text style={styles.metricLabel}>{label}</Text></View>}
function translate(s:string){return({pending:"قيد المراجعة",approved:"معتمد",paid:"مدفوع",rejected:"مرفوض"} as Record<string,string>)[s]||s}
function statusColor(s:string){return s==="paid"?"#16A34A":s==="rejected"?"#E11D48":s==="approved"?"#2563EB":"#D97706"}
const styles=StyleSheet.create({header:{height:62,paddingHorizontal:13,backgroundColor:"#FFF",flexDirection:"row-reverse",alignItems:"center",gap:9,borderBottomWidth:1,borderColor:"#ECECEC"},iconBtn:{width:38,height:38,alignItems:"center",justifyContent:"center"},headerCopy:{flex:1,alignItems:"flex-end"},title:{fontSize:16,fontWeight:"900",color:"#111"},subtitle:{fontSize:9,color:"#999",marginTop:2},headerIcon:{width:36,height:36,borderRadius:11,backgroundColor:"#111",alignItems:"center",justifyContent:"center"},page:{padding:12,paddingBottom:130,maxWidth:760,width:"100%",alignSelf:"center"},hero:{backgroundColor:"#111",borderRadius:20,padding:18,marginBottom:10},heroTop:{flexDirection:"row-reverse",alignItems:"center",gap:8},heroIcon:{width:38,height:38,borderRadius:12,backgroundColor:"#E11D48",alignItems:"center",justifyContent:"center"},heroLabel:{fontSize:11,color:"#C8C8C8",fontWeight:"800"},heroAmount:{fontSize:31,fontWeight:"900",color:"#FFF",textAlign:"right",marginTop:12},heroCurrency:{fontSize:13,color:"#AAA"},heroMeta:{marginTop:14,paddingTop:10,borderTopWidth:1,borderColor:"#2A2A2A",flexDirection:"row",justifyContent:"space-between"},heroMetaText:{fontSize:9,color:"#8E8E8E"},metrics:{flexDirection:"row-reverse",gap:8,marginBottom:12},metric:{flex:1,backgroundColor:"#FFF",borderRadius:13,borderWidth:1,borderColor:"#ECECEC",padding:11,alignItems:"flex-end"},metricIcon:{width:30,height:30,borderRadius:10,backgroundColor:"#F4F4F5",alignItems:"center",justifyContent:"center",marginBottom:7},metricValue:{fontSize:14,fontWeight:"900",color:"#111",maxWidth:"100%"},metricLabel:{fontSize:9,color:"#888",marginTop:2},card:{backgroundColor:"#FFF",borderRadius:15,borderWidth:1,borderColor:"#ECECEC",padding:14,marginBottom:13},cardHead:{flexDirection:"row-reverse",alignItems:"center",gap:9,marginBottom:12},cardIcon:{width:31,height:31,borderRadius:10,backgroundColor:"#FFF1F2",alignItems:"center",justifyContent:"center"},cardTitle:{fontSize:14,fontWeight:"900",color:"#111",textAlign:"right"},cardHint:{fontSize:9,color:"#999",marginTop:2,textAlign:"right"},amountField:{height:48,borderRadius:11,backgroundColor:"#F7F7F8",borderWidth:1,borderColor:"#E7E7E8",flexDirection:"row-reverse",alignItems:"center",paddingHorizontal:8,marginBottom:10},currencyPill:{fontSize:9,color:"#777",fontWeight:"900",paddingHorizontal:8},input:{flex:1,fontSize:16,fontWeight:"800",color:"#111",paddingHorizontal:10},primary:{height:44,borderRadius:22,backgroundColor:"#E11D48",flexDirection:"row-reverse",gap:7,alignItems:"center",justifyContent:"center"},disabled:{opacity:.55},primaryText:{fontSize:12,color:"#FFF",fontWeight:"900"},sectionHead:{flexDirection:"row-reverse",justifyContent:"space-between",alignItems:"center",marginBottom:7},sectionTitle:{fontSize:14,fontWeight:"900",color:"#111"},sectionHint:{fontSize:9,color:"#999"},payout:{flexDirection:"row-reverse",alignItems:"center",justifyContent:"space-between",paddingVertical:12,borderTopWidth:1,borderColor:"#F0F0F0",gap:10},firstPayout:{borderTopWidth:0},payoutCopy:{flex:1,alignItems:"flex-end"},payoutAmount:{fontSize:13,fontWeight:"900",color:"#111"},reference:{fontSize:9,color:"#777",marginTop:2},date:{fontSize:8,color:"#AAA",marginTop:2},statusPill:{flexDirection:"row-reverse",alignItems:"center",gap:5,paddingHorizontal:8,paddingVertical:5,borderRadius:99,backgroundColor:"#F7F7F8"},statusDot:{width:6,height:6,borderRadius:3},statusText:{fontSize:9,fontWeight:"900"},empty:{alignItems:"center",paddingVertical:35},emptyText:{fontSize:11,color:"#999",marginTop:8},muted:{fontSize:12,color:"#777"},center:{flex:1,alignItems:"center",justifyContent:"center",gap:9}});
